const { app, BrowserWindow } = require('electron')
const fs = require('node:fs'), path = require('node:path'), XLSX = require('xlsx'), { build } = require('esbuild')
const { renderSpreadsheetDocument } = require('../../desktop/services/spreadsheet-preview.cjs')
const { renderMarkdownDocument } = require('../../desktop/services/preview.cjs')
const root = path.resolve(__dirname, '../..'), out = path.join(root, 'qa-artifacts/document-browser')
fs.mkdirSync(out, { recursive: true }); app.setPath('userData', fs.mkdtempSync(path.join(out, 'profile-'))); app.disableHardwareAcceleration()
async function main() {
  await app.whenReady()
  const win = new BrowserWindow({ show: false, width: 720, height: 850, webPreferences: { sandbox: true, offscreen: true } })
  const book = XLSX.utils.book_new()
  XLSX.utils.book_append_sheet(book, XLSX.utils.aoa_to_sheet([['门店', 'GMV', '备注'], ['A店', 120, '<script>alert(1)</script>'], ['B店', 240, '长内容']]), '会员经营')
  XLSX.utils.book_append_sheet(book, XLSX.utils.aoa_to_sheet([['月份', '会员数'], ['九月', 36]]), '月报')
  const file = path.join(out, 'test.xlsx'); XLSX.writeFile(book, file)
  const before = fs.readFileSync(file)
  const load = html => win.loadURL('data:text/html;charset=utf-8,' + encodeURIComponent(html))
  await load(renderSpreadsheetDocument(file, 'light'))
  await win.webContents.executeJavaScript(`if(!document.querySelector('table').textContent.includes('A店'))throw Error('Missing cells');if(document.querySelector('script'))throw Error('Unsafe content');document.querySelector('label[for="sheet-1"]').click();true`)
  await win.webContents.executeJavaScript(`if(getComputedStyle(document.querySelector('#sheet-panel-1')).display==='none'||getComputedStyle(document.querySelector('#sheet-panel-0')).display!=='none')throw Error('Sheet switching failed');true`)
  fs.writeFileSync(path.join(out, 'spreadsheet.png'), (await win.webContents.capturePage()).toPNG())
  if (!before.equals(fs.readFileSync(file))) throw Error('Source changed')
  await load(renderMarkdownDocument('# 会员经营报告\n\n## 本月结论\n\n- 会员运营\n  - 复购提升\n  - 留存分析\n\n| 门店 | GMV |\n| --- | --- |\n| A店 | 120 |\n\n```js\nconst value = 120;\n```', '报告.md', 'light'))
  await win.webContents.executeJavaScript(`if(!document.querySelector('li ul')||!document.querySelector('table')||!document.querySelector('pre code'))throw Error('Markdown formatting failed');true`)
  fs.writeFileSync(path.join(out, 'markdown.png'), (await win.webContents.capturePage()).toPNG())
  const bundle = (await build({ stdin: { contents: `import React from 'react';import{createRoot}from'react-dom/client';import{BrowserPanel}from'./src/BrowserPanel';window.calls=[];window.stable={browser:{command:async p=>{window.calls.push(p);return{tabs:[],downloads:[]}},onChanged:()=>()=>{}}};createRoot(document.getElementById('root')).render(<BrowserPanel conversationId="test" onClose={()=>{}} onImport={()=>{}}/>);`, resolveDir: root, loader: 'tsx' }, bundle: true, write: false, format: 'iife' })).outputFiles[0].text
  await load('<div id="root"></div>'); await win.webContents.executeJavaScript(bundle)
  await new Promise(resolve => setTimeout(resolve, 200))
  await win.webContents.executeJavaScript(`const input=document.querySelector('[aria-label="网页地址"]');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,'example.com');input.dispatchEvent(new Event('input',{bubbles:true}));true`)
  await new Promise(resolve => setTimeout(resolve, 100))
  await win.webContents.executeJavaScript(`document.querySelector('form').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));true`)
  await new Promise(resolve => setTimeout(resolve, 100))
  await win.webContents.executeJavaScript(`if(!window.calls.some(p=>p.action==='create'&&p.url==='https://example.com'))throw Error('Address navigation failed');true`)
  win.destroy(); console.log('DOCUMENT_BROWSER_UI_PASSED'); app.exit(0)
}
main().catch(error => { console.error(error); app.exit(1) })
